python3 - <<'EOF'
import json, glob, math

total = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
        if elapsed is None:
            continue
        v = elapsed['value']
        u = elapsed['unit']
        if u == 'ms':
            total += v
        elif u == 'us':
            total += v // 1000
        elif u == 's':
            total += v * 1000
        else:
            raise ValueError(u)
print(total)
EOF
